function header(){const r=route();return `<div class="top-utility"><div class="shell flex between"><span>${icon('leaf',14)} AGRICULTURE INTELLIGENCE FOR EVERY GROWER</span><span>${icon('shield',13)} Private browser-based farm workspace <span class="utility-dot">•</span> Not an official advisory</span></div></div><header class="header"><div class="shell header-inner"><a href="#/home" class="brand" aria-label="KrishiMitra One home"><span class="brand-mark">${icon('leaf',26)}</span><span class="brand-word">KrishiMitra<span class="brand-accent">.</span><small>GROW SMARTER. FARM BETTER.</small></span></a><form id="global-search" class="site-search">${icon('search',20)}<input name="search" aria-label="Search crops" placeholder="Search crops, guides, farming tools..."/><button type="submit">Search ${icon('arrow',15)}</button></form><div class="header-actions"><a class="utility-header-link" href="#/weather" title="Weather">${icon('sun',19)}<span>Weather</span></a><label class="language">${icon('globe',17)}<select id="language" aria-label="Language"><option value="en" ${state.settings.lang==='en'?'selected':''}>English</option><option value="mr" ${state.settings.lang==='mr'?'selected':''}>मराठी</option><option value="hi" ${state.settings.lang==='hi'?'selected':''}>हिंदी</option></select></label><a href="#/dashboard" class="header-farm-btn">${icon('user',17)} My farm</a><button data-action="menu" class="mobile-menu" title="Open menu" aria-label="Toggle navigation">${icon('menu',22)}</button></div></div></header><nav class="nav-bar ${ui.menu?'nav-open':''}"><div class="shell nav-inner">${[['home','Home','home'],['crops','Explore crops','sprout'],['advisor','Crop-fit advisor','flask'],['planner','Crop planning','calendar'],['market','Market hub','store'],['weather','Weather','sun'],['learn','Knowledge','book'],['finance','Finance & schemes','wallet']].map(([route,label,ico])=>A(route,`${icon(ico,16)}<span>${label}</span>`,r===route?'nav-link active':'nav-link')).join('')}<span class="nav-spacer"></span>${A('dashboard',`${icon('grid',16)} <span>Farm workspace</span>`,'nav-link nav-workspace')}</div></nav>`}
function footer(){return `<footer class="footer"><div class="shell footer-grid"><div><div class="footer-logo"><img src="./assets/logo.svg"/>KrishiMitra<span>.</span></div><p>Grow with confidence. One place to organize the everyday work behind better farming.</p><div class="privacy-note">${icon('lock',15)} Your records stay in this browser in this version.</div></div><div><b>Explore</b>${A('crops','Crop catalogue')}${A('market','Market hub')}${A('learn','Knowledge centre')}</div><div><b>My workspace</b>${A('dashboard','Farm dashboard')}${A('tasks','Daily tasks')}${A('reports','Backups & reports')}</div><div><b>Information</b>${A('about','About & limitations')}<a href="https://enam.gov.in/" target="_blank" rel="noopener noreferrer">e-NAM official ${icon('external',13)}</a><a href="https://soilhealth.dac.gov.in/" target="_blank" rel="noopener noreferrer">Soil Health Card ${icon('external',13)}</a></div></div><div class="shell footer-bottom"><span>© 2026 KrishiMitra · Educational farmer workspace</span><span>No live commerce or medical-grade crop diagnosis</span></div></footer>`}
