function advisor(){return `<div class="shell page-section"><div class="page-mini-hero"><div><span class="hero-label">${icon('flask',16)} INTERACTIVE CROP-FIT EXPLORER</span><h2>Better questions.<br>Smarter crop planning.</h2><p>Compare crop guides with your soil, growing season and water availability using a transparent rule-based model.</p></div></div>${head('CROP SUITABILITY EXPLORER','Explore crop fit for your field','An educational screening tool—not a laboratory diagnosis, agronomic recommendation, or yield forecast.')}<div class="advisor-layout"><form id="advisor-form" class="panel advisor-form"><h3>Tell us about your field</h3><p>Use your actual soil test report whenever available.</p><label>Soil pH (from test report)<input type="number" name="ph" min="3" max="10" step="0.1" value="6.5" required/></label><label>Main soil texture<select name="soil"><option>Loamy</option><option>Clay</option><option>Black</option><option>Sandy</option></select></label><label>Water availability<select name="water"><option>Medium</option><option>Low</option><option>High</option></select></label><label>Growing season<select name="season"><option>Kharif</option><option>Rabi</option><option>Multiple</option></select></label><button type="submit" class="btn btn-green">Compare crops ${icon('arrow',17)}</button></form><div class="panel advisor-result" id="advisor-results"><div class="advisor-placeholder">${icon('sprout',52)}<h3>Explore possible crop matches</h3><p>Enter your field details and choose Compare crops to see how our crop catalogue aligns with the selected conditions.</p><span>Matches are guides, not planting approval.</span></div></div></div><div class="section-callout">${icon('shield',18)} This comparison uses broad catalogue labels, not a validated crop recommendation model. It does not use a region-specific variety database, laboratory nutrient thresholds, actual water volumes, disease pressure or up-to-date market forecasts. Confirm with a local agricultural extension expert.</div></div>`}
function advisorResults(form){const f=new FormData(form),ph=Number(f.get('ph')),soil=String(f.get('soil')),water=String(f.get('water')),season=String(f.get('season'));if(!Number.isFinite(ph)||ph<3||ph>10){notice('Enter soil pH between 3 and 10.');return}const ranked=crops.map(c=>{let pts=0;let reasons=[];if(c.soil===soil){pts+=40;reasons.push('Catalogue soil texture aligns')}else reasons.push('Different catalogue soil preference');if(c.water===water){pts+=35;reasons.push('Water category aligns')}else reasons.push('Check irrigation needs');if(c.season===season||c.season==='Multiple'||c.season==='Long duration'||c.season==='Perennial'){pts+=25;reasons.push('Season compatible in broad guide')}else reasons.push('Season differs from broad guide');return {c,pts,reasons}}).sort((a,b)=>b.pts-a.pts);const pHHint=ph<5.5?'Acidic soil observation—ask your soil testing lab for crop-specific interpretation.':ph>7.5?'Alkaline soil observation—ask your soil testing lab for crop-specific interpretation.':'Recorded pH is in a commonly encountered range; suitability remains crop- and location-specific.';document.querySelector('#advisor-results').innerHTML=`<div class="advisor-top"><span class="section-eyebrow">PRELIMINARY CATALOGUE MATCHES</span><h3>Crop guide comparisons</h3><p>${esc(pHHint)}</p></div><div class="advisor-list">${ranked.slice(0,7).map((x,i)=>`<div class="advisor-match"><span class="advisor-emoji">${x.c.emoji}</span><div><strong>${esc(x.c.name)}</strong><small>${esc(x.c.season)} · ${esc(x.c.water)} water · ${esc(x.c.soil)} soil</small><span>${esc(x.reasons.slice(0,2).join(' · '))}</span></div><span class="match-badge">${x.pts}/100 <small>catalogue fit</small></span></div>`).join('')}</div><div class="advisor-disclaimer">Scores compare only three general catalogue labels. Soil pH is displayed separately, and the number is not a probability of crop success.</div>${A('planner',`Plan a crop ${icon('arrow',16)}`,'btn btn-green')}`}
function cropLibrary(){const filtered=filterCrops(crops,{query:ui.q,category:ui.category,season:ui.season,sort:ui.sort});return `<div class="shell page-section"><div class="page-mini-hero mini-crops"><div><span class="hero-label">${icon('sprout',16)} CROP KNOWLEDGE LIBRARY</span><h2>Every crop has a story.<br>Start with the right information.</h2><p>Browse diverse crops, compare seasons, and save what interests you.</p></div></div>${head('GROWING KNOWLEDGE','Explore crop catalogue','Find crops across seasons and regions. Suitability depends on local climate, soil tests and verified agronomic advice.')}
<div class="toolbar"><div class="input-search">${icon('search',19)}<input id="crop-search" type="search" aria-label="Search crops by name or category" aria-controls="crop-results" placeholder="Search crops by name or category" value="${esc(ui.q)}"/><button id="clear-crop-search" class="crop-search-clear" type="button" aria-label="Clear crop search"${ui.q?'':' hidden'}>Clear search</button></div><div class="toolbar-select">${icon('filter',16)}<select id="crop-category" aria-label="Category">${['All',...new Set(crops.map(c=>c.group))].map(x=>`<option ${ui.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="toolbar-select"><select id="crop-season" aria-label="Growing season">${['All','Kharif','Rabi','Multiple','Long duration','Perennial'].map(x=>`<option ${ui.season===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="toolbar-select"><select id="crop-sort" aria-label="Sort crops"><option value="name">Name A–Z</option><option value="duration" ${ui.sort==='duration'?'selected':''}>Shorter duration first</option><option value="water" ${ui.sort==='water'?'selected':''}>Water level</option></select></div></div><div class="result-count" role="status" aria-live="polite">${filtered.length} crops in this collection</div><div id="crop-results" class="crops-grid" aria-live="polite">${filtered.map(cropCard).join('')||empty('search','No crops found','Try a different crop name or category.')}</div><div class="section-callout">${icon('info',20)} Season and duration values are general examples; confirm local suitability, planting dates and seed varieties with extension experts before taking decisions.</div></div>`}
function market(){const l=state.listings.filter(x=>`${x.crop} ${x.location}`.toLowerCase().includes(ui.marketQ.toLowerCase()));return `<div class="shell page-section">${head('PRODUCE & TRADE','Farm marketplace hub','Discover crop categories, organize your produce listings and compare buyer offers. Public buying and selling is not enabled yet.',btn(`${icon('plus',17)} Create listing draft`,'open','listing'))}
<div class="market-hero"><div><span class="eyebrow light">FARM TO MARKET</span><h2>A better way to prepare for selling.</h2><p>Document available produce, track quotations and understand your net return before you trade.</p>${A('prices',`Compare buyer quotations ${icon('arrow',17)}`,'btn btn-lime')}</div><div class="market-glyph">${icon('store',108)}</div></div>
<div class="section-title-row in-page"><div><h2>Browse produce categories</h2><p>Explore what's grown and planned across different seasons.</p></div></div><div class="market-categories">${['Grains','Vegetables','Fruits','Pulses','Oilseeds','Cash crops','Spices'].map(k=>{let c=crops.find(x=>x.group===k);return `<a href="#/crops" data-category="${k}" class="market-category"><span class="market-emoji">${c?.emoji||'🌱'}</span><strong>${k}</strong><small>Explore crops ${icon('arrow',13)}</small></a>`}).join('')}</div>
<div class="section-title-row in-page"><div><h2>My produce listing drafts</h2><p>Only you can see these on this device. They are not published to a public marketplace.</p></div>${btn(`Add a listing ${icon('plus',16)}`,'open','listing','btn btn-outline')}</div><div class="listing-list">${l.length?l.map(x=>`<article class="listing-card"><div class="listing-emoji">${crops.find(c=>c.name===x.crop)?.emoji||'🌾'}</div><div><h3>${esc(x.crop)}</h3><p>${esc(x.quantity)} ${esc(x.unit)} • ${esc(x.location||'Location not set')}</p>${pill('Private draft','amber')}</div><div class="listing-price"><b>${money(x.price)}</b><small>Asking price / ${esc(x.unit)}</small></div>${rowActions('listings',x.id)}</article>`).join(''):empty('store','No listing drafts yet','Create your first produce listing to keep details ready for future buyer conversations.',btn(`${icon('plus',16)} Create draft`,'open','listing'))}</div>
<div class="section-callout">${icon('shield',20)} KrishiMitra does not currently process real orders, collect payments, verify buyers or publish your listings. Use trusted official trading channels such as <a href="https://enam.gov.in/" target="_blank" rel="noopener noreferrer">e-NAM ${icon('external',13)}</a>.</div></div>`}
function workNav(active='dashboard'){const opts=[['dashboard','Overview','layout'],['farm','My farm','home'],['soil','Soil health','flask'],['planner','Crop planning','sprout'],['tasks','Farm tasks','calendar'],['health','Crop health','activity'],['harvest','Harvest & yield','wheat'],['prices','Market quotes','trending'],['storage','Storage','package'],['finance','Finances','wallet'],['reports','Data & backups','file']];return `<div class="workspace-nav" aria-label="Farm tools">${opts.map(([r,n,i])=>A(r,`${icon(i,16)} ${n}`,r===active?'active':'')).join('')}</div>`}
function workWrap(route,content){return `<div class="shell workspace-shell"><div class="workspace-label">${icon('layout',16)} MY FARM WORKSPACE <span> / ${esc(route.replace(/\b\w/g,m=>m.toUpperCase()))}</span></div>${workNav(route)}${content}${footnote()}</div>`}
function dashboard(){const cost=total(state.ledger.filter(x=>x.type==='Expense'),'amount'),rev=total(state.ledger.filter(x=>x.type==='Income'),'amount'),outstanding=state.tasks.filter(x=>x.status!=='done');const name=state.profile.name?.trim();return workWrap('dashboard',`${head('YOUR FARM AT A GLANCE',`Good to see you${name?', '+esc(name.split(' ')[0]):''}! 👋`,'One simple place to manage your land, crop plans and daily work.',btn(`${icon('plus',17)} Add daily task`,'open','task'))}<div class="dashboard-intro"><div><span>FARM PROFILE</span><h2>${esc(state.profile.location||'Your growing journey starts here')}</h2><p>${state.profile.area?`${esc(state.profile.area)} ${esc(state.profile.unit)} of farm area recorded.`:'Start by adding your farm location and growing area to personalize your workspace.'}</p>${A('farm',`Manage farm profile ${icon('arrow',16)}`,'btn btn-white')}</div><div class="dash-farm-mark">${icon('sprout',112)}</div></div><div class="stats-grid">${stat('Crop plans',state.plans.length,'sprout','Across your fields')}${stat('Tasks to do',outstanding.length,'calendar','Not yet completed')}${stat('Recorded expenses',money(cost),'wallet','Based on saved transactions')}${stat('Recorded balance',money(rev-cost),'trending','Income minus expenses')}</div><div class="dashboard-columns"><section class="panel"><div class="panel-title"><div><h3>Daily tasks</h3><p>Keep your next action visible.</p></div>${A('tasks',`View all ${icon('arrow',16)}`,'text-link')}</div>${outstanding.length?`<div class="task-list">${outstanding.slice(0,5).map(t=>`<div class="task-item"><button class="task-check" aria-label="Complete task" data-action="complete" data-value="${esc(t.id)}">${icon('check',17)}</button><div><b>${esc(t.title)}</b><span>${esc(t.crop||'General')} • ${t.due?dateFmt(t.due):'No due date'}</span></div>${pill(dueLabel(t.due),t.due&&t.due<today()?'danger':'soft')}</div>`).join('')}</div>`:empty('calendar','A clear day ahead','Add irrigation, scouting or field tasks and see them here.',btn('Add first task','open','task','btn btn-outline btn-sm'))}</section><section class="panel"><div class="panel-title"><div><h3>Active crop plans</h3><p>Your growing season, organized.</p></div>${A('planner',`All plans ${icon('arrow',16)}`,'text-link')}</div>${state.plans.length?`<div class="mini-plans">${state.plans.slice(-4).reverse().map(t=>`<div class="mini-plan"><span>${crops.find(c=>c.name===t.crop)?.emoji||'🌱'}</span><div><b>${esc(t.crop)}</b><small>${esc(t.plot||'Unassigned plot')} · ${t.sowing?dateFmt(t.sowing):'Date not set'}</small></div>${pill(esc(t.stage||'Planned'))}</div>`).join('')}</div>`:empty('sprout','No crops planned yet','Browse the crop catalogue and create your first seasonal plan.',btn('Plan a crop','open','plan','btn btn-outline btn-sm'))}</section></div><div class="section-title-row in-page"><div><h2>Every tool you need</h2><p>Choose what you want to work on next.</p></div></div><div class="services-grid compact">${services.map(s=>`<a href="${link(s.route)}" class="service-card"><span class="service-icon ${s.color}">${icon(s.icon,22)}</span><h3>${s.title}</h3><p>${s.desc}</p><span class="service-chevron">${icon('arrow',18)}</span></a>`).join('')}</div>`)}
function farm(){return workWrap('farm',`${head('FARM DETAILS','My farm profile','Keep your growing details in one place. This information stays on your device.',btn(`${icon('edit',17)} Edit profile`,'open','farm'))}<div class="profile-grid"><div class="panel farm-profile"><div class="farm-avatar">${icon('sprout',49)}</div><h2>${esc(state.profile.name||'Your farm is waiting')}</h2><p>${esc(state.profile.location||'Add your village, city or region')} ${state.profile.country?'· '+esc(state.profile.country):''}</p>${pill('Private browser profile','soft')}<div class="detail-rows"><div><span>Growing area</span><b>${state.profile.area?`${esc(state.profile.area)} ${esc(state.profile.unit)}`:'Not set'}</b></div><div><span>Main soil type</span><b>${esc(state.profile.soilType||'Not set')}</b></div><div><span>Location</span><b>${esc(state.profile.location||'Not set')}</b></div></div>${btn('Update details','open','farm','btn btn-green block')}</div><div class="panel"><div class="panel-title"><div><h3>Make your farm workspace yours</h3><p>A good profile helps your records stay organized.</p></div></div><div class="steps-list"><div><span>1</span><p><b>Enter your farm location</b><small>Any village, city or region worldwide.</small></p></div><div><span>2</span><p><b>Record your farm area</b><small>Choose acres or hectares.</small></p></div><div><span>3</span><p><b>Start a crop plan</b><small>Build a season-specific growing plan.</small></p></div></div>${A('planner',`Go to crop planning ${icon('arrow',17)}`,'btn btn-outline')}</div></div>`)}
function recordsTable(rows,columns,key,emptyText){if(!rows.length)return empty('file','No records yet',emptyText);return `<div class="table-scroll"><table class="records-table"><thead><tr>${columns.map(c=>`<th>${c[0]}</th>`).join('')}<th></th></tr></thead><tbody>${rows.slice().reverse().map(item=>`<tr>${columns.map(([label,field,format])=>`<td>${format?format(item[field],item):esc(item[field]||'—')}</td>`).join('')}<td>${rowActions(key,item.id)}</td></tr>`).join('')}</tbody></table></div>`}
function soil(){return workWrap('soil',`${head('KNOW YOUR LAND','Soil health records','Keep lab test results and compare broad soil indicators. Always follow a certified soil laboratory’s recommendations.',btn(`${icon('plus',17)} Add soil test`,'open','soil'))}<div class="stats-grid three">${stat('Tests recorded',state.soil.length,'flask','With lab reference details')}${stat('Latest pH',state.soil.length?esc(state.soil.at(-1).ph||'—'):'—','activity','Based on your latest entry')}${stat('Soil type',esc(state.profile.soilType||'Not set'),'sprout','From your farm profile')}</div><section class="panel"><div class="panel-title"><div><h3>Soil test history</h3><p>Lab results, nutrient readings and observations.</p></div></div>${recordsTable(state.soil,[['Date','date',dateFmt],['Plot','plot'],['pH','ph'],['pH indicator','ph',scoreSoilPH],['N / P / K','n',(_,r)=>`${esc(r.n||'—')} / ${esc(r.p||'—')} / ${esc(r.k||'—')}`]],'soil','Add your first laboratory test result to begin tracking soil health.')}</section><div class="section-callout">${icon('info',20)} pH tags use broad, general ranges only. NPK values require units, testing method and a local soil expert to interpret; the platform does not calculate fertilizer prescriptions.</div>`)}
function planner(){return workWrap('planner',`${head('SEASON PLANNING','Crop planner','Capture when and where you plan to grow each crop. Duration is a catalogue estimate, not a local prediction.',btn(`${icon('plus',17)} New crop plan`,'open','plan'))}<div class="planner-layout"><div class="panel"><div class="panel-title"><div><h3>Your crop plans</h3><p>${state.plans.length} crop plans saved</p></div></div>${state.plans.length?`<div class="plans-grid">${state.plans.slice().reverse().map(p=>`<div class="plan-tile"><span class="plan-icon">${crops.find(c=>c.name===p.crop)?.emoji||'🌱'}</span><div><h3>${esc(p.crop)}</h3><p>${esc(p.plot||'Unassigned field')}</p></div>${pill(p.stage||'Planned')}<div class="plan-details"><span>Sowing: <b>${p.sowing?dateFmt(p.sowing):'Not set'}</b></span><span>Area: <b>${esc(p.area||'—')} ${esc(p.unit||state.profile.unit)}</b></span></div>${rowActions('plans',p.id)}</div>`).join('')}</div>`:empty('sprout','A plan for every season','Start with a crop, planting date and farm plot.',btn('Create first crop plan','open','plan'))}</div><aside class="panel side-panel"><h3>Planning checklist</h3><div class="checklist-static"><span>${icon('check',15)} Confirm your local season</span><span>${icon('check',15)} Match crop and soil conditions</span><span>${icon('check',15)} Estimate water availability</span><span>${icon('check',15)} Choose certified seed sources</span><span>${icon('check',15)} Record expected harvest window</span></div>${A('crops',`Browse crop catalogue ${icon('arrow',16)}`,'btn btn-outline block')}</aside></div>`)}
function tasks(){const pending=state.tasks.filter(x=>x.status!=='done'),completed=state.tasks.filter(x=>x.status==='done');return workWrap('tasks',`${head('EVERYDAY OPERATIONS','Daily farm tasks','Stay organized across irrigation, crop scouting, field work and reminders.',btn(`${icon('plus',17)} Add task`,'open','task'))}<div class="stats-grid three">${stat('To do',pending.length,'calendar','Tasks remaining')}${stat('Completed',completed.length,'check','All recorded work')}${stat('Watering notes',state.water.length,'cloud','Saved irrigation entries')}</div><div class="dashboard-columns"><section class="panel"><div class="panel-title"><div><h3>To-do list</h3><p>Click the circle to mark any task complete.</p></div></div>${pending.length?pending.map(t=>`<div class="task-item spaced"><button class="task-check" data-action="complete" data-value="${esc(t.id)}" title="Mark complete">${icon('check',16)}</button><div><b>${esc(t.title)}</b><span>${esc(t.crop||'General')} · ${t.due?dateFmt(t.due):'No due date'}</span></div>${pill(dueLabel(t.due),t.due&&t.due<today()?'danger':'soft')}${rowActions('tasks',t.id)}</div>`).join(''):empty('check','No outstanding tasks','Add your next activity or enjoy a clear checklist.')}${completed.length?`<h4 class="subheading">Completed</h4>${completed.slice(-4).reverse().map(t=>`<div class="task-item done-task"><span class="done-mark">${icon('check',14)}</span><div><b>${esc(t.title)}</b><span>${esc(t.crop||'General')}</span></div>${rowActions('tasks',t.id)}</div>`).join('')}`:''}</section><section class="panel"><div class="panel-title"><div><h3>Watering journal</h3><p>Track irrigation by plot and date.</p></div>${btn(`${icon('plus',15)} Log`,'open','water','btn btn-outline btn-sm')}</div>${state.water.length?state.water.slice(-6).reverse().map(r=>`<div class="compact-record"><span>${icon('cloud',17)}</span><div><b>${esc(r.plot)}</b><small>${dateFmt(r.date)} · ${esc(r.method||'Method not set')}</small></div><b>${esc(r.quantity||'—')}</b>${rowActions('water',r.id)}</div>`).join(''):empty('cloud','No watering logged','Save watering dates and quantities as you work.')}</section></div>`)}
function health(){return workWrap('health',`${head('FIELD OBSERVATIONS','Crop health journal','Save photos, symptoms and crop observations. This is a record-keeping tool, not an automated disease diagnosis.',btn(`${icon('plus',17)} Add observation`,'open','health'))}<div class="section-callout top">${icon('shield',20)} Crop images and symptom notes cannot establish a reliable diagnosis. Consult a qualified agricultural extension worker before treatment or pesticide use.</div><div class="observations">${state.observations.length?state.observations.slice().reverse().map(r=>`<article class="observation-card">${r.photo?`<img src="${r.photo}" alt="Uploaded field observation"/>`:`<div class="photo-placeholder">${icon('activity',35)}</div>`}<div><div class="overline">${dateFmt(r.date)} · ${esc(r.crop)}</div><h3>${esc(r.symptom)}</h3><p>${esc(r.notes||'No notes recorded')}</p>${pill('Needs local verification','amber')}</div>${rowActions('observations',r.id)}</article>`).join(''):empty('activity','Start a crop health journal','Take field notes and attach optional plant photos to help explain symptoms to an expert.',btn('Add first observation','open','health'))}</div>`)}
function harvest(){return workWrap('harvest',`${head('HARVEST MANAGEMENT','Harvest & yield','Estimate a scenario and compare it with actual harvest records. This is a calculator, not an AI yield forecast.',btn(`${icon('plus',17)} Record harvest`,'open','harvest'))}<div class="dashboard-columns"><div class="panel"><div class="panel-title"><div><h3>Yield scenario calculator</h3><p>Enter your own expected yield per unit of area.</p></div></div><form id="yield-calculator" class="form-grid"><label>Field area<input required type="number" min="0.01" step="0.01" name="area" placeholder="Example: 2.5" value="2.5"/></label><label>Expected yield (kg / area unit)<input required type="number" min="0" step="0.01" name="rate" value="1200"/></label><label>Area unit<select name="unit"><option>acre</option><option>hectare</option></select></label><button type="submit" class="btn btn-green">Calculate scenario ${icon('arrow',16)}</button></form><div id="yield-result" class="calculation-output"><small>Illustrative scenario</small><strong>3,000 kg</strong><p>2.5 acres × 1,200 kg/acre. Your result is not a prediction.</p></div></div><div class="panel"><div class="panel-title"><div><h3>Actual harvests</h3><p>What your farm really produced.</p></div></div>${state.harvests.length?state.harvests.slice(-6).reverse().map(r=>`<div class="compact-record"><span class="harvest-emoji">${crops.find(c=>c.name===r.crop)?.emoji||'🌾'}</span><div><b>${esc(r.crop)}</b><small>${dateFmt(r.date)} · ${esc(r.plot||'General')}</small></div><b>${num(r.quantity)} kg</b>${rowActions('harvests',r.id)}</div>`).join(''):empty('wheat','No harvest records yet','Save each harvest quantity for future comparisons.')}</div></div>`)}
function prices(){const arr=[...state.quotes].sort((a,b)=>netReturn(b.price,b.quantity,b.transport,b.other)-netReturn(a.price,a.quantity,a.transport,a.other));return workWrap('prices',`${head('SELL WITH CLARITY','Market prices & buyer quotes','Compare offers you have entered. For verified mandi rates use official market services.',btn(`${icon('plus',17)} Add buyer quote`,'open','quote'))}<div class="market-sourcebar">${icon('info',20)} No live mandi prices are shown here. Official references: <a href="https://enam.gov.in/" target="_blank" rel="noopener noreferrer">e-NAM ${icon('external',12)}</a> <a href="https://agmarknet.gov.in/" target="_blank" rel="noopener noreferrer">AGMARKNET ${icon('external',12)}</a></div><div class="stats-grid three">${stat('Saved quotations',arr.length,'trending','Enter your own verified offers')}${stat('Highest net return',arr.length?money(netReturn(arr[0].price,arr[0].quantity,arr[0].transport,arr[0].other)):'—','chart','Based on estimated costs')}${stat('Latest crop',arr.length?esc(state.quotes.at(-1).crop):'—','sprout','From your last saved quote')}</div><div class="panel"><div class="panel-title"><div><h3>Buyer quotation comparison</h3><p>Ordered by estimated net proceeds. Verify units and quality grades.</p></div></div>${recordsTable(arr,[['Buyer / market','buyer'],['Crop','crop'],['Price / kg','price',v=>money(v)],['Quantity (kg)','quantity',num],['Est. net proceeds','price',(_,r)=>`<b>${money(netReturn(r.price,r.quantity,r.transport,r.other))}</b>`]],'quotes','Add two or more buyer quotes to compare estimated returns.')}</div>`)}
function storage(){return workWrap('storage',`${head('AFTER HARVEST','Storage & supply chain','Keep track of stored produce, batch quality and dispatch status.',btn(`${icon('plus',17)} Add storage batch`,'open','lot'))}<div class="stats-grid three">${stat('Stored batches',state.lots.length,'package','All recorded inventory')}${stat('Stored quantity',`${num(total(state.lots,'quantity'))} kg`,'wheat','Across entered batches')}${stat('Dispatched',state.lots.filter(x=>x.status==='Dispatched').length,'truck','Lots marked dispatched')}</div><section class="panel"><div class="panel-title"><div><h3>Produce batch tracker</h3><p>Record lot identifiers for traceability.</p></div></div>${recordsTable(state.lots,[['Batch ID','batch'],['Crop','crop'],['Quantity','quantity',v=>`${num(v)} kg`],['Storage location','location'],['Status','status',v=>pill(v,v==='Dispatched'?'soft':'amber')]],'lots','Start a new storage batch and track its quality and movement.')}</section><div class="section-callout">${icon('info',20)} Storage conditions are crop-specific. Confirm suitable moisture levels, safe practices and storage standards with qualified professionals.</div>`)}
function finance(){const income=total(state.ledger.filter(x=>x.type==='Income'),'amount'),expense=total(state.ledger.filter(x=>x.type==='Expense'),'amount');return workWrap('finance',`${head('KEEP A CLEAR PICTURE','Farm finance & support','See recorded income, expenses and available official government resources.',btn(`${icon('plus',17)} New transaction`,'open','transaction'))}<div class="stats-grid three">${stat('Total recorded income',money(income),'trending','From saved transactions')}${stat('Total recorded expenses',money(expense),'wallet','From saved transactions')}${stat('Recorded balance',money(income-expense),'chart','Not a full profit calculation')}</div><div class="dashboard-columns"><section class="panel"><div class="panel-title"><div><h3>Recent transactions</h3><p>Your income and expense notebook.</p></div></div>${state.ledger.length?state.ledger.slice(-9).reverse().map(r=>`<div class="compact-record"><span class="type-dot ${r.type==='Income'?'income':'expense'}">${icon(r.type==='Income'?'trending':'wallet',17)}</span><div><b>${esc(r.title)}</b><small>${dateFmt(r.date)} · ${esc(r.category)}</small></div><b class="${r.type==='Income'?'positive':'negative'}">${r.type==='Income'?'+':'−'}${money(r.amount)}</b>${rowActions('ledger',r.id)}</div>`).join(''):empty('wallet','No transactions yet','Record your first income or expense to see a running balance.')}</section><section class="panel"><div class="panel-title"><div><h3>Official farmer resources</h3><p>Verify eligibility and conditions on each official site.</p></div></div>${sources.filter(s=>/Government of India/.test(s.label)).map(s=>`<a class="resource-row" href="${s.url}" target="_blank" rel="noopener noreferrer"><span class="resource-icon">${icon('external',20)}</span><div><b>${esc(s.title)}</b><small>${esc(s.type)}</small></div>${icon('arrow',17)}</a>`).join('')}</section></div>`)}
function weather(){const loc=state.weatherLocation;return `<div class="shell page-section">${head('GLOBAL WEATHER','Weather for your farm','Search any city or region to view a current weather snapshot and multi-day outlook, powered by Open-Meteo.')}
<div class="weather-banner"><div><span class="eyebrow light">PLAN AHEAD</span><h2>Know the conditions before you head to the field.</h2><p>Weather changes fast. Always check local warnings and observe actual conditions.</p><form id="weather-search" class="weather-form"><input name="city" required minlength="2" placeholder="Enter a city, village or region" value="${esc(ui.cityQuery||loc?.name||'')}"/><button class="btn btn-lime" type="submit">${icon('search',17)} Find weather</button></form></div><div class="weather-bigicon">${icon('sun',118)}</div></div><div id="weather-output">${ui.weatherBusy?`<div class="weather-status">Searching for weather…</div>`:ui.weatherError?`<div class="section-callout">${icon('info',20)} ${esc(ui.weatherError)}</div>`:ui.weather?weatherRender(ui.weather):empty('cloud','Choose your location','Weather is only loaded when you search. Internet access is needed.')}</div><div class="section-callout">${icon('info',20)} Forecasts are not local safety alerts or field-specific agronomic recommendations. Location and weather data are provided by Open-Meteo. <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Attribution ${icon('external',13)}</a>.</div></div>`}
function weatherRender(w){return `<div class="weather-result"><div class="current-weather"><small>Current conditions in ${esc(w.name)}</small><h3>${Math.round(w.current.temperature_2m)}°C ${icon('sun',32)}</h3><p>Wind: ${num(w.current.wind_speed_10m)} km/h · Relative humidity: ${num(w.current.relative_humidity_2m)}%</p><small>Data at ${esc(w.current.time||'—').replace('T',' ')}</small></div><div class="forecast-list">${w.daily.time.map((d,i)=>`<div><span>${dateFmt(d)}</span><b>${Math.round(w.daily.temperature_2m_max[i])}° / ${Math.round(w.daily.temperature_2m_min[i])}°</b><small>${num(w.daily.precipitation_sum[i])} mm rain</small></div>`).join('')}</div></div>`}
function learn(){return `<div class="shell page-section">${head('FARM KNOWLEDGE CENTRE','Learn, improve, grow','Short guidance notes and links to authoritative services. All recommendations should be tailored by a local agricultural professional.')}
<div class="learn-grid wide">${learning.map((x,i)=>`<article class="learn-card"><div class="learn-visual learn-${i}">${icon(x.icon,34)}</div><div>${pill(x.category)}<h3>${esc(x.title)}</h3><p>${esc(x.body)}</p><span>${icon('clock',15)} ${x.time} read</span></div></article>`).join('')}</div><div class="section-title-row in-page"><div><h2>Trusted information sources</h2><p>Use official portals to verify agriculture data and scheme eligibility.</p></div></div><div class="sources-grid">${sources.map(s=>`<a class="source-card" href="${s.url}" target="_blank" rel="noopener noreferrer"><span>${icon('external',20)}</span><b>${esc(s.title)}</b><p>${esc(s.type)}</p><small>${esc(s.label)} ${icon('arrow',14)}</small></a>`).join('')}</div></div>`}
function reports(){const collections=[['Soil reports','soil'],['Crop plans','plans'],['Daily tasks','tasks'],['Irrigation logs','water'],['Crop health notes','observations'],['Harvest records','harvests'],['Buyer quotes','quotes'],['Storage batches','lots'],['Finance records','ledger'],['Listing drafts','listings']];return workWrap('reports',`${head('YOUR INFORMATION','Records & backups','A simple place to review, download and restore your farm data.',btn(`${icon('download',17)} Export backup`,'backup'))}<div class="report-grid"><section class="panel"><h3>Your saved records</h3><p>What you have recorded on this device so far.</p><div class="record-count-grid">${collections.map(([n,k])=>`<div><span>${n}</span><strong>${state[k].length}</strong></div>`).join('')}</div><div class="report-note">${icon('lock',18)} Your data is local to this browser. It is not synced to a server or shared with other farmers.</div></section><section class="panel backup-panel"><div class="backup-illustration">${icon('shield',43)}</div><h3>Keep a backup of your work</h3><p>Save a copy to your phone or computer. Backups contain any photos and personal farm information you entered.</p>${btn(`${icon('download',17)} Download JSON backup`,'backup','','btn btn-green block')}<div class="divider"></div><h4>Restore a backup</h4><p>Select a previously exported KrishiMitra JSON file. Restoring will replace the saved records on this browser.</p><label class="upload-zone">${icon('upload',19)} Choose backup JSON<input type="file" id="restore-input" accept="application/json,.json"/></label><div class="divider"></div>${btn(`${icon('download',17)} Export transactions CSV`,'csv','','btn btn-outline block')}<p class="tiny">Avoid importing files from anyone you do not trust.</p></section></div><div class="danger-panel"><div><h3>Clear local records</h3><p>Remove all saved farm data from this browser. This cannot be undone without a backup.</p></div>${btn('Clear records','clear','','btn btn-danger')}</div>`)}
function about(){return `<div class="shell page-section">${head('ABOUT KRISHIMITRA','A friendlier way to manage farming','A thoughtfully designed starter platform for growers, small farms and agricultural learning.')}
<div class="about-hero"><div><span class="eyebrow light">FARMER-FIRST BY DESIGN</span><h2>Technology should make farming simpler—not more complicated.</h2><p>KrishiMitra brings crop exploration, farm diaries and financial records into an accessible, responsive website that farmers can use from anywhere.</p>${A('dashboard',`Explore the workspace ${icon('arrow',17)}`,'btn btn-lime')}</div>${icon('sprout',135)}</div><div class="section-title-row in-page"><div><h2>What works—and what's next</h2></div></div><div class="about-cards"><div class="panel"><span class="pill soft">AVAILABLE IN THIS VERSION</span><h3>Works today</h3><ul><li>Crop catalogue and season filters</li><li>Farm profiles and offline browser records</li><li>Crop plans, tasks, irrigation and harvest logs</li><li>Private market listing drafts and quotation comparisons</li><li>Expenses, income, storage and backups</li><li>Location-based weather requests with network access</li></ul></div><div class="panel"><span class="pill amber">NEEDED BEFORE LARGE-SCALE LAUNCH</span><h3>Production roadmap</h3><ul><li>Secure user accounts and cloud database</li><li>Verified sellers, real marketplace, payments and fulfillment</li><li>Full Marathi/Hindi and more languages</li><li>Independent accessibility and security review</li><li>Field-validated crop advice and professional oversight</li><li>Consent, privacy policy, backup and data deletion processes</li></ul></div></div><div class="section-callout">${icon('info',20)} This version is a functional demonstration and private record-keeping MVP. It is not yet a secure multi-user farmer service. Please do not rely on it for chemical treatment, disease diagnosis, financing eligibility or live market transactions.</div></div>`}
const formDefs={
farm:{title:'Set up your farm',subtitle:'Tell us about your growing space. You can update this later.',fields:[['name','Farm or farmer name','text','e.g. Green Valley Farm'],['location','Village, city or region','text','e.g. Nashik, Maharashtra'],['country','Country','text','e.g. India'],['currency','Currency','select','INR|USD|EUR|GBP|BDT|NPR|PKR|LKR|AUD|CAD'],['area','Farm area','number','e.g. 3.5'],['unit','Area unit','select','acre|hectare'],['soilType','Main soil type','select','Unknown|Black|Red|Clay|Loamy|Sandy|Alluvial|Other'],['notes','Notes','textarea','Main crops, climate or anything useful']]},
soil:{title:'Record soil test',subtitle:'Copy readings exactly from your lab report. Use consistent measurement units.',fields:[['date','Test date','date'],['plot','Field / plot','text','e.g. North field'],['ph','pH reading','number','e.g. 6.8'],['n','Nitrogen (lab reported value)','text','Include units'],['p','Phosphorus (lab reported value)','text','Include units'],['k','Potassium (lab reported value)','text','Include units'],['notes','Laboratory / notes','textarea','Lab name, method and interpretation']]},
plan:{title:'Create crop plan',subtitle:'Start a plan and review local sowing conditions separately.',fields:[['crop','Crop','crop'],['plot','Field / plot name','text','e.g. East field'],['sowing','Planned sowing date','date'],['area','Planned growing area','number','e.g. 2'],['unit','Area unit','select','acre|hectare'],['stage','Status','select','Planned|Sown|Growing|Harvested']]},
task:{title:'Add a farm task',subtitle:'Record the next thing your farm needs.',fields:[['title','Task name','text','e.g. Scout tomato plants'],['crop','Crop / plot','text','e.g. Tomato field'],['due','Due date','date'],['notes','Task notes','textarea','What to check or do']]},
water:{title:'Add irrigation log',subtitle:'Save what was watered and when.',fields:[['date','Watering date','date'],['plot','Field / plot','text','e.g. West field'],['method','Method','select','Drip|Sprinkler|Flood|Manual|Other'],['quantity','Quantity / duration','text','e.g. 45 minutes'],['notes','Notes','textarea','Moisture observations']]},
health:{title:'Crop health observation',subtitle:'Document symptoms and photos. This does not diagnose diseases.',fields:[['date','Observation date','date'],['crop','Crop','crop'],['symptom','Visible symptom','text','e.g. Yellowing leaves'],['notes','Description','textarea','Affected area, plant stage, weather, etc.'],['photo','Optional plant photo','file','Upload a photo']]},
harvest:{title:'Record actual harvest',subtitle:'Keep an accurate harvest journal.',fields:[['date','Harvest date','date'],['crop','Crop','crop'],['plot','Field / plot','text','e.g. Main field'],['quantity','Quantity harvested (kg)','number','e.g. 1200'],['notes','Harvest notes','textarea','Quality, grade, etc.']]},
quote:{title:'Add buyer quotation',subtitle:'Use comparable quality grades and same units to compare correctly.',fields:[['buyer','Buyer / market name','text','e.g. Buyer A'],['crop','Crop','crop'],['price','Price per kg','number','e.g. 35'],['quantity','Quantity in kg','number','e.g. 500'],['transport','Transport cost (total)','number','e.g. 250'],['other','Other costs (total)','number','e.g. 120']]},
lot:{title:'Add a storage batch',subtitle:'Keep batch details for inventory and dispatch tracking.',fields:[['batch','Batch reference','text','e.g. LOT-01'],['crop','Crop','crop'],['quantity','Quantity (kg)','number','e.g. 250'],['location','Storage location','text','e.g. Warehouse A'],['status','Batch status','select','In storage|Quality check|Ready to ship|Dispatched'],['notes','Quality notes','textarea','Storage conditions and observations']]},
transaction:{title:'Record income or expense',subtitle:'Track money moving in and out of your farm.',fields:[['type','Transaction type','select','Expense|Income'],['date','Date','date'],['title','Description','text','e.g. Seeds purchase'],['category','Category','select','Seeds|Fertilizer|Water|Labour|Machinery|Transport|Crop sales|Rent|Other'],['amount','Amount','number','e.g. 1500']]},
listing:{title:'Create produce listing draft',subtitle:'Private listing only. It is not visible to buyers or other users.',fields:[['crop','Produce / crop','crop'],['quantity','Available quantity','number','e.g. 1000'],['unit','Unit','select','kg|quintal|tonne'],['price','Asking price per unit','number','e.g. 32'],['location','Produce location','text','e.g. Pune, Maharashtra'],['notes','Quality / grade notes','textarea','Harvest date or product notes']]}
};
const typeMap={soil:'soil',plan:'plans',task:'tasks',water:'water',health:'observations',harvest:'harvests',quote:'quotes',lot:'lots',transaction:'ledger',listing:'listings'};
function modal(){if(!ui.dialog)return '';if(ui.dialog.kind==='crop'){const c=crops.find(c=>c.id===ui.dialog.value);if(!c)return '';return `<div class="modal-overlay" id="overlay"><section class="modal crop-modal" role="dialog" aria-modal="true" aria-labelledby="modal-head"><button class="modal-close" data-action="close" aria-label="Close">${icon('close',21)}</button>${imageCrop(c)}<div class="modal-content"><span class="eyebrow">CROP OVERVIEW</span><h2 id="modal-head">${esc(c.name)}</h2><p>${esc(c.detail)}</p><div class="crop-modal-facts"><div><small>Typical season</small><b>${esc(c.season)}</b></div><div><small>Approx. duration</small><b>${c.duration} days</b></div><div><small>Water need</small><b>${esc(c.water)}</b></div><div><small>Example soil</small><b>${esc(c.soil)}</b></div></div><div class="section-callout">Actual variety, timing, fertilizer and care depend on local conditions and lab advice.</div><div class="modal-actions">${btn('Close','close','','btn btn-outline')}${btn(`${icon('plus',17)} Plan this crop`,'plan-crop',c.name)}</div></div></section></div>`}
const def=formDefs[ui.dialog.kind];if(!def)return '';const editing=ui.dialog.kind==='farm';const initial=editing?state.profile:{};return `<div class="modal-overlay" id="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-head"><div class="modal-header"><div><div class="eyebrow">KRISHIMITRA WORKSPACE</div><h2 id="modal-head">${def.title}</h2><p>${def.subtitle}</p></div><button class="modal-close" data-action="close" aria-label="Close">${icon('close',22)}</button></div><form id="record-form" data-kind="${ui.dialog.kind}" class="modal-form"><div class="form-grid">${def.fields.map(([key,label,kind,hint])=>`<label class="${kind==='textarea'||kind==='file'?'full':''}">${esc(label)}${kind==='select'?`<select name="${key}">${hint.split('|').map(v=>`<option value="${esc(v)}" ${initial[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:kind==='crop'?`<select name="${key}">${crops.map(v=>`<option ${initial[key]===v.name||ui.dialog.prefill===v.name?'selected':''}>${v.name}</option>`).join('')}</select>`:kind==='textarea'?`<textarea name="${key}" rows="3" placeholder="${esc(hint||'')}">${esc(initial[key]||'')}</textarea>`:kind==='file'?`<input name="${key}" type="file" accept="image/*"/>`:`<input name="${key}" type="${kind}" ${kind==='number'?'min="0" step="any"':''} value="${esc(initial[key]||((kind==='date'&&key==='date')?today():''))}" placeholder="${esc(hint||'')}" ${['name','location','title','symptom','batch','buyer','quantity','amount','price'].includes(key)?'required':''}/>`}</label>`).join('')}</div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close">Cancel</button><button type="submit" class="btn btn-green">${icon('check',17)} Save ${editing?'profile':'record'}</button></div></form></section></div>`}
function render(){const r=route();const map={home,advisor,crops:cropLibrary,market,dashboard,farm,soil,planner,tasks,health,harvest,prices,storage,finance,weather,learn,reports,about};$('#app').innerHTML=header()+`<main id="main">${map[r]()}</main>`+footer()+`<div class="mobile-tabbar">${nav.slice(0,5).map(n=>A(n.route,`${icon(n.icon,21)}<small>${n.label==='Explore crops'?'Crops':n.label==='Market hub'?'Market':n.label==='My farm'?'My farm':n.label}</small>`,n.route===r?'active':'' )).join('')}</div>`+modal()+`<div id="toast" class="toast ${ui.toast?'show':''}" role="status">${icon('check',17)} ${esc(ui.toast)}</div>`;document.body.classList.toggle('dialog-open',!!ui.dialog);if(ui.dialog)setTimeout(()=>$('#record-form input:not([type="hidden"]), .modal-close')?.focus(),30)}
function notice(m){ui.toast=m;let el=$('#toast');if(el){el.innerHTML=`${icon('check',17)} ${esc(m)}`;el.classList.add('show')}else render();clearTimeout(notice.timeout);notice.timeout=setTimeout(()=>{ui.toast='';let x=$('#toast');if(x)x.classList.remove('show')},3600)}
function show(kind,prefill=''){ui.dialog={kind,prefill};render()}
function openCrop(id){ui.dialog={kind:'crop',value:id};render()}
function close(){ui.dialog=null;render()}
function csvEscape(v){const text=String(v??'');return '"'+( /^[=+@\-\t\r]/.test(text) ? '\''+text : text).replaceAll('"','""')+'"'}
function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function doAction(action,val){if(action==='menu'){ui.menu=!ui.menu;render();return}if(action==='goto'){location.hash=link(val);return}if(action==='close'){close();return}if(action==='open'){show(val);return}if(action==='crop'){openCrop(val);return}if(action==='plan-crop'){show('plan',val);return}if(action==='favorite'){state.favorites=state.favorites.includes(val)?state.favorites.filter(x=>x!==val):[...state.favorites,val];save();render();notice('Favorites updated');return}if(action==='complete'){const t=state.tasks.find(x=>x.id===val);if(t){t.status='done';save();render();notice('Task completed')}return}if(action==='delete'){const [type,id]=val.split(':');if(!Array.isArray(state[type]))return;if(confirm('Delete this record? This cannot be undone unless you have a backup.')){state[type]=state[type].filter(x=>x.id!==id);save();render();notice('Record deleted')}return}if(action==='backup'){download(`KrishiMitra-backup-${today()}.json`,JSON.stringify({format:'KrishiMitra-next',version:1,exportedAt:new Date().toISOString(),data:state},null,2),'application/json');notice('Your backup has been downloaded');return}if(action==='csv'){const lines=[['Date','Type','Description','Category','Amount'],...state.ledger.map(x=>[x.date,x.type,x.title,x.category,x.amount])].map(x=>x.map(csvEscape).join(','));download(`KrishiMitra-finances-${today()}.csv`,lines.join('\n'),'text/csv;charset=utf-8');return}if(action==='clear'){if(confirm('Clear ALL KrishiMitra records from this browser? Export a backup first.'))if(confirm('Final confirmation: permanently remove locally saved farm data?')){state=emptyState();setCurrency('INR');save();render();notice('Local records cleared')}return}}
async function photoToData(file){if(!file)return '';if(file.size>8*1024*1024)throw Error('Photo must be smaller than 8 MB');return new Promise((resolve,reject)=>{const img=new Image();const reader=new FileReader();reader.onload=()=>{img.onload=()=>{let scale=Math.min(1,640/Math.max(img.width,img.height));let cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.width*scale));cv.height=Math.max(1,Math.round(img.height*scale));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);resolve(cv.toDataURL('image/jpeg',.65))};img.onerror=()=>reject(Error('Invalid image'));img.src=String(reader.result)};reader.onerror=()=>reject(Error('Cannot read photo'));reader.readAsDataURL(file)})}
async function recordSubmit(form){const kind=form.dataset.kind;const fd=new FormData(form);const obj={};for(let [k,v] of fd.entries())if(!(v instanceof File))obj[k]=String(v).trim();if(kind==='health'){let file=fd.get('photo');if(file instanceof File&&file.size){try{obj.photo=await photoToData(file)}catch(e){notice(e.message);return}}}if(kind==='farm'){state.profile={...state.profile,...obj};setCurrency(state.profile.currency);if(!obj.name?.trim()||!obj.location?.trim()){notice('Farm name and location are required');return}}else {obj.id=uid();obj.createdAt=new Date().toISOString();if(kind==='task')obj.status='todo';state[typeMap[kind]].push(obj)}save();ui.dialog=null;render();notice(kind==='farm'?'Farm profile saved':'Record saved successfully')}
async function findWeather(city){ui.cityQuery=city;ui.weatherBusy=true;ui.weatherError='';ui.weather=null;render();try{const resp=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1&language=en&format=json`);if(!resp.ok)throw Error('Location search is unavailable');let data=await resp.json();let loc=data.results?.[0];if(!loc)throw Error('No matching location found. Try a nearby city or a more specific place name.');const url=`https://api.open-meteo.com/v1/forecast?latitude=${loc.latitude}&longitude=${loc.longitude}&current=temperature_2m,relative_humidity_2m,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=auto&forecast_days=5`;let wx=await fetch(url);if(!wx.ok)throw Error('Weather information is unavailable right now');let data2=await wx.json();ui.weather={...data2,name:`${loc.name}, ${loc.admin1?loc.admin1+', ':''}${loc.country}`};state.weatherLocation={name:city,latitude:loc.latitude,longitude:loc.longitude};save()}catch(e){ui.weatherError=`${e.message}. Check your internet connection or try another location.`}finally{ui.weatherBusy=false;render()}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b){e.preventDefault();doAction(b.dataset.action,b.dataset.value||'')}let cat=e.target.closest('[data-category]');if(cat){e.preventDefault();ui.category=cat.dataset.category;ui.q='';location.hash=link('crops');render()}if(e.target.id==='overlay')close()});
document.addEventListener('click',e=>{if(!e.target.closest('#clear-crop-search'))return;e.preventDefault();ui.q='';const input=$('#crop-search');if(input)input.value='';updateCrops();if(input)input.focus()});
document.addEventListener('submit',async e=>{const f=e.target;if(['global-search','quick-search','weather-search','record-form','yield-calculator','advisor-form'].includes(f.id))e.preventDefault();if(f.id==='advisor-form'){advisorResults(f);return}if(f.id==='global-search'||f.id==='quick-search'){const fd=new FormData(f);ui.q=String(fd.get('search')||fd.get('q')||'').trim();ui.category='All';location.hash=link('crops');render();return}if(f.id==='weather-search'){findWeather(String(new FormData(f).get('city')||'').trim());return}if(f.id==='record-form'){await recordSubmit(f);return}if(f.id==='yield-calculator'){const fd=new FormData(f),area=Number(fd.get('area')),rate=Number(fd.get('rate')),unit=fd.get('unit');$('#yield-result').innerHTML=`<small>Illustrative yield scenario</small><strong>${num(yieldEstimate(area,rate))} kg</strong><p>${num(area)} ${esc(unit)} × ${num(rate)} kg/${esc(unit)}. This is not a forecast.</p>`;return}});
document.addEventListener('input',e=>{if(e.target.id==='crop-search'){ui.q=e.target.value;updateCrops()} });
function updateCrops(){const cards=$('#crop-results');if(!cards)return;const list=filterCrops(crops,{query:ui.q,category:ui.category,season:ui.season,sort:ui.sort});cards.innerHTML=list.map(cropCard).join('')||empty('search','No crops found','Try another term.');const counter=$('.result-count');if(counter)counter.textContent=`${list.length} crops in this collection`;const clearButton=$('#clear-crop-search');if(clearButton)clearButton.hidden=!ui.q}
document.addEventListener('change',async e=>{if(e.target.id==='language'){state.settings.lang=e.target.value;save();render();notice('Language preference saved. Some detailed content remains in English.')}if(e.target.id==='crop-category'){ui.category=e.target.value;updateCrops()}if(e.target.id==='crop-season'){ui.season=e.target.value;updateCrops()}if(e.target.id==='crop-sort'){ui.sort=e.target.value;updateCrops()}if(e.target.id==='restore-input'){let file=e.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup is too large');const obj=JSON.parse(await file.text());if(obj.format!=='KrishiMitra-next'||!obj.data||typeof obj.data!=='object')throw Error('This is not a compatible KrishiMitra backup');if(confirm('This will replace all current local records. Continue?')){state=safeState(obj.data);setCurrency(state.profile.currency);save();render();notice('Backup restored successfully')}}catch(err){notice(err.message||'Could not restore backup')}}});
window.addEventListener('hashchange',()=>{ui.menu=false;ui.dialog=null;render();window.scrollTo({top:0,behavior:'instant'})});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.dialog)close()});
render();
if('serviceWorker' in navigator && /^https?:/.test(location.protocol)){
  window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
}
